using DentalDashboard.LeadManagement.Contract; using DentalDashboard.Domain.Enums; using DentalDashboard.Domain.Models; using DentalDashboard.Infrastracture.Context; using Microsoft.EntityFrameworkCore;
namespace DentalDashboard.LeadManagement.Application;
public sealed class AdminLeadSheetService(DentalContext db) : IAdminLeadSheetService {
 public async Task<AdminLeadSheet> CreateSheetAsync(string name,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Sheet name is required.");var s=new AdminLeadSheet{Name=name.Trim(),CreatedAt=DateTime.UtcNow};db.AdminLeadSheets.Add(s);await db.SaveChangesAsync(ct);return s;}
 public async Task<AdminSheetLead> AddLeadAsync(long id,string phone,string first,string last,CancellationToken ct=default){if(!await db.AdminLeadSheets.AnyAsync(x=>x.Id==id&&x.IsActive,ct))throw new KeyNotFoundException("Sheet not found.");phone=Normalize(phone);if(!System.Text.RegularExpressions.Regex.IsMatch(phone,"^09\\d{9}$"))throw new ArgumentException("Invalid Iranian mobile number.");if(string.IsNullOrWhiteSpace(first)||string.IsNullOrWhiteSpace(last))throw new ArgumentException("FirstName and LastName are required.");var r=new AdminSheetLead{AdminLeadSheetId=id,PhoneNumber=phone,FirstName=first.Trim(),LastName=last.Trim(),CreatedAt=DateTime.UtcNow};db.AdminSheetLeads.Add(r);await db.SaveChangesAsync(ct);return r;}
 public async Task<int> ProcessPendingAsync(CancellationToken ct=default){var rows=await db.AdminSheetLeads.Where(x=>x.ProcessingStatus==0).OrderBy(x=>x.Id).Take(200).ToListAsync(ct);foreach(var r in rows){try{if(!await db.LeadAssignments.AnyAsync(x=>x.PhoneNumber==r.PhoneNumber&&!x.IsDeleted,ct)){var l=new LeadAssignment{UserName=$"{r.FirstName} {r.LastName}".Trim(),PhoneNumber=r.PhoneNumber,CreatedAt=DateTime.Now,AssignmentType=LeadAssignmentType.RealTime,RequiresThreeMinuteCall=true,LeadAssignmentState=LeadAssignmentState.New,SourceType=LeadSourceType.AdminSheet};db.LeadAssignments.Add(l);await db.SaveChangesAsync(ct);r.LeadAssignmentId=l.Id;}r.ProcessingStatus=1;r.ProcessedAt=DateTime.UtcNow;}catch(Exception e){r.ProcessingStatus=2;r.ErrorMessage=e.Message;}}await db.SaveChangesAsync(ct);return rows.Count;}
 static string Normalize(string v){var s=(v??"").Trim().Replace(" ","").Replace("-","");if(s.StartsWith("+98"))s="0"+s[3..];if(s.StartsWith("98")&&s.Length==12)s="0"+s[2..];if(s.StartsWith("9")&&s.Length==10)s="0"+s;return s;}
}
